const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const items=templateConfiguration.items.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,30);const state=input.state||{};if(input.event.action==='update')state.checked=items.map((_,i)=>!!input.event.form['item'+i]);const checked=state.checked||[];
return {html:'<main><p>PLANNING</p><h1>'+esc(templateConfiguration.heading)+'</h1><form data-action="update">'+items.map((item,i)=>'<label><input type="checkbox" name="item'+i+'" '+(checked[i]?'checked':'')+'>'+esc(item)+'</label>').join('')+'<button>Update progress</button></form><h2>'+checked.filter(Boolean).length+' / '+items.length+'</h2><p>Progress lasts for this session; it is not a saved record or approval.</p></main>',css:'body{font:16px system-ui;color:#193c31;background:#f4f7f5;margin:0}main{max-width:640px;margin:40px auto;padding:28px}label{display:flex;gap:12px;padding:16px;margin:8px 0;background:white;border-radius:8px}button{padding:12px 24px;background:#175f47;color:white;border:0;border-radius:8px}',state};
